                if distance[node] + new_graph[node][neighbor] < distance[neighbor]:
                    distance[neighbor] = distance[node] + new_graph[node][neighbor]

    # Step 3: Run Bellman-Ford algorithm again to find the shortest path from all nodes to the sink node
    reverse_distance = {node: float('inf') for node in new_graph}
    reverse_distance['t'] = 0
    for _ in range(len(new_graph) - 1):
