            residual_graph[node][parent[node]] += path_flow
            node = parent[node]

    # Step 6: Calculate the maximum flow
    max_flow = 0
    for node in residual_graph:
        for neighbor in residual_graph[node]:
            max_flow += residual_graph[node][neighbor]

    return max_flow
