```sql
CREATE DEFINER=`root`@`%` FUNCTION `fun_get_tw_area_all`(twCode varchar(100)) RETURNS varchar(2000) CHARSET utf8mb3
BEGIN   
DECLARE str varchar(1000) DEFAULT '';  -- 区域名称 
DECLARE temp varchar(100) DEFAULT '';  -- 临时区域名称
DECLARE fcode varchar(100) DEFAULT '';  -- 父级code
DECLARE level int DEFAULT 0;  -- 层级
DECLARE max_level int DEFAULT 0;  -- 最大层级
DECLARE cursor_area CURSOR FOR
    SELECT `code`, `name`, upcode, level FROM tw_area_info WHERE is_delete = '0' and `code` = twCode;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET @continue = TRUE;
OPEN cursor_area;
read_loop: LOOP
    FETCH cursor_area INTO fcode, temp, upcode, level;
    IF @continue THEN
        LEAVE read_loop;
    END IF;
    IF level > max_level THEN
        SET max_level = level;
    END IF;
    IF level = 0 THEN
        SET str = temp;
    ELSE
        SET str = concat(temp, '-', str);
    END IF;
END LOOP;
CLOSE cursor_area;
SET str = TRIM( TRAILING '-' FROM str);
return str;
END;
```
