  { Supplier: "ABC", SKU: "Product A", Original Price: 100, New Price: 90, Amount Taken Away: 10 },
  { Supplier: "ABC", SKU: "Product B", Original Price: 200, New Price: 180, Amount Taken Away: 20 },
  { Supplier: "DEF", SKU: "Product C", Original Price: 300, New Price: 270, Amount Taken Away: 30 }
];

// calculate the flow of money
var flowData = [];
data.forEach(function(d) {
  flowData.push({
    source: d.Supplier,
    target: d.SKU,
    value: d.Amount Taken Away
  });
});

// calculate the percentage taken away
