```cpp
#include <iostream>
#include <string>
#include <libssh2.h>
#include <libssh2_sftp.h>

using namespace std;

int main() {
    // Initialize SSH2 session
    LIBSSH2_SESSION *session = libssh2_session_init();
    if (!session) {
        cout << "Failed to initialize SSH2 session" << endl;
        return 1;
    }

    // Connect to the server
    if (libssh2_connect(session, "example.com", 22) != LIBSSH2_ERROR_NONE) {
        cout << "Failed to connect to the server" << endl;
        libssh2_session_free(session);
        return 1;
    }

    // Login to the server
    if (libssh2_userauth_password(session, "username", "password") != LIBSSH2_AUTH_SUCCESS) {
        cout << "Failed to login to the server" << endl;
        libssh2_session_free(session);
        return 1;
    }

    // Execute a command on the remote server
    LIBSSH2_CHANNEL *channel = libssh2_channel_open_session(session);
    if (!channel) {
        cout << "Failed to open a channel" << endl;
        libssh2_session_free(session);
        return 1;
    }

    string command = "ls -l";
    char *cmd = new char[command.size() + 1];
    strcpy(cmd, command.c_str());
    libssh2_channel_exec(channel, cmd);
    delete[] cmd;

    // Read the output of the command
    char buffer[1024];
    while (libssh2_channel_read(channel, buffer, 1024) > 0) {
        cout << buffer << endl;
    }

    // Close the channel and the session
    libssh2_channel_close(channel);
    libssh2_channel_free(channel);
    libssh2_session_free(session);

    return 0;
}
