```cpp
#include <QApplication>
#include <QUrl>
#include <QNetworkRequest>
#include <QNetworkAccessManager>
#include <QFile>
#include <QTextStream>
#include <QMessageBox>

class MySpider : public QObject {
    Q_OBJECT
public:
    MySpider(QObject *parent = 0) : QObject(parent) {
        // 设置网络请求管理器
        _nam = new QNetworkAccessManager(this);
        connect(_nam, &QNetworkAccessManager::finished, this, &MySpider::onFinished);
    }

    void start(const QUrl &url) {
        // 发送网络请求
        _nam->get(QNetworkRequest(url));
    }

    void exportData(const QString &data) {
        // 保存数据到文件
        QFile file("data.txt");
        if (!file.open(QFile::WriteOnly | QFile::Text)) {
            QMessageBox::critical(this, "Error", "Failed to open file");
            return;
        }
        QTextStream out(&file);
        out << data;
        file.close();
    }

private slots:
    void onFinished(QNetworkReply *reply) {
        // 处理网络请求结果
        if (reply->error()) {
            QMessageBox::critical(this, "Error", "Failed to load page");
            return;
        }
        QString data = reply->readAll();
        // 处理数据
        // ...
        // 导出数据
        exportData(data);
        // 点击下一页
        QUrl nextPageUrl = QUrl("http://example.com/next");
        start(nextPageUrl);
    }

private:
    QNetworkAccessManager *_nam;
};

int main(int argc, char **argv) {
    QApplication app(argc, argv);

    MySpider spider;
    spider.start(QUrl("http://example.com/first"));
    return app.exec();
}

#include "main.moc"
```
这个demo程序使用QNetworkAccessManager来发送网络请求，并使用QTextStream来保存数据到文件。`onFinished`槽函数处理网络请求结果，处理数据，导出数据，然后点击下一页。

注意：这个demo程序只是一个简单的示例，实际上你可能需要处理更多的错误和异常，例如网络连接失败、页面加载失败等。

